/**
 * Copy for the /laboratory-tests page: the price list built from the
 * hospital's own catalogue (`catalogue.ts`, generated by
 * `npm run lab:import`).
 *
 * Every figure about the catalogue is a `{template}` filled by the page from
 * `labCatalogueSummary`, never typed here: `{count}`, `{fromPrice}`,
 * `{sameDayCount}`. `{opdDiscount}` is read from the laboratory service
 * entry in `services/data/diagnostics.ts`, which owns the 10%. content.test.ts
 * pins both.
 *
 * `featuredCodes` are the eight tests people ask for most, by catalogue code,
 * with the short name the hero ticker shows; the price always comes from the
 * catalogue. The home page's own teaser band carries the same eight in
 * `home/data/content.ts` so its test can pin them without reaching in here.
 *
 * The hero, the eyebrows, the headings, the CTAs and the filter row stay
 * English in every locale (docs/superpowers/i18n-register-rule.md); the
 * intros, the empty state and the count line translate in content.si.ts and
 * content.ta.ts.
 */
import type { BookAction, FactRow, FeaturedTest } from "../types.ts";

export const hero = {
  strapline: "Laboratory price list",
  breadcrumbHome: "Home",
  breadcrumbCurrent: "Laboratory tests",
  headingLead: "Every test.",
  headingAccent: "One honest price.",
  bookCta: "Book a test",
  call: { value: "0117 84 84 84" },
};

export const heroStandfirst =
  "Our laboratory runs at every hour, most reports come back the same day, and every report is read by two doctors before it reaches you. Here is every test we run and what it costs, from {fromPrice} LKR.";

/** The third cell renders in accent. */
export const heroFacts: FactRow[] = [
  { k: "Tests", v: "{count}" },
  { k: "From", v: "{fromPrice} LKR" },
  { k: "Same day", v: "{sameDayCount}" },
  { k: "OPD discount", v: "{opdDiscount}" },
];

